head.script:
scwin.isMain = function() {
	return true;
};
/* mypinFlag */
scwin.mypinFlag = false;
scwin.mypinXcordi = '';
scwin.mypinYcordi = '';

scwin.zoomLevelBtnArr = [];

scwin.userId = "";

/* 탭 변경여부 */
scwin.tapInit = false;

/* 탭 클릭 인덱스 */
scwin.clicked = 0;

/* 넘겨받은 데이터 */
scwin.param = '';

scwin.onpageload = function() {
	// window 오픈시 경로 못찾아서 직접 넣어줘야함
	scscrno.setSystmCtxtPath('/pgj')
	scscrno.setScPgmId('PGJ152F00');
	sccdo.setSystm(scglblo.SYSTM.PGJ);
	sccdo.loadIntgCdLst(scglblo.SYSTM.PGJ + scglblo.DELIMITER.HYPHEN + 'DSPSL_GDS_LST_USG_CD');
	scwin.userId = WebSquare.cookie.getCookie('cortAuctnLgnMbr');
	//scwin.userId = "ttest11a";
	scwin.zoomLevelBtnArr.push(zoomLevelValue_1);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_2);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_3);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_4);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_5);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_6);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_7);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_8);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_9);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_10);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_11);
	scwin.zoomLevelBtnArr.push(zoomLevelValue_12);

	//탭 초기화
	tab_mapTapCtr.hideTab(4);
	tab_mapTapCtr.hideTab(5);
	tab_mapTapCtr.hideTab(6);
	const paramObj = com.data.getParameter("paramObj") || JSON.parse(WebSquare.util.getPopupParam()) || '';
	scwin.param = JSON.stringify(paramObj.info);
	if (!scutilo.isEmpty(paramObj)) {
		scwin.tapMoveEvent(paramObj);
	}

	scwin.setMap(paramObj);
	btn_myPin.hide(); //관심지역 탭에서만 오픈

	/* 웹접근성 Enter이벤트를 추가하기 위한 로직 */
	const levelDiv = document.querySelectorAll('.map_level');
	levelDiv.forEach(el=>{
		const aTags = el.querySelectorAll('a');
		aTags.forEach(a=>{
			a.addEventListener('keydown',function(e){
				let key = e.key || e.which || e.keyCode;
				if (key == 'Enter' || key == 1) {
					let zoom = this.id.slice(9);
					if(zoom == "minus"){
						scwin.minusZoom();
					} else if(zoom == "plus"){
						scwin.plusZoom();
					} else {
						scwin.changeZoom(zoom);
					}
				}
			});
		});
	});
};

scwin.setMap = function(param){

	pgjMap(new FreeMapMap('mf_map'));
	pgjMap.getMap().enableWheelZoom();

	//초기맵 셋팅
	let x = "312757";
	let y = "544471";
	let title = "서울중앙지방법원";
	if (!scutilo.isEmpty(param) && !scutilo.isEmpty(param.info.x) && !scutilo.isEmpty(param.info.y)) {
		x = param.info.x;
		y = param.info.y;
	} else {
		//지도검색시 마커
		pgjMap.makeMarker({
			x: x
			, y: y
			, title: title
		});
	}

	//중심값
	pgjMap.getMap().setCenterAndZoomLevel(x, y, 10);

	//기본줌
	scwin.mgnZoomBox(10);

	FreeMapEvent.addListener(pgjMap.getMap(), "zoom", function(newZoom, oldZoom){
		scwin.mgnZoomBox(newZoom);
	})
}

scwin.mgnZoomBox = function(zoom){
	for(let i = 1; i <= 12; i++){
		const btn = scwin.zoomLevelBtnArr[i-1];
		let src = '/pgj/cm/images/map/level_empty.gif';
		if(i <= zoom){
			src = '/pgj/cm/images/map/level_fill.gif';
		}
		btn.setSrc(src);
		zoomLevel.setSrc('/pgj/cm/images/map/level_' + String(zoom < 10? '0' + zoom : zoom) + '.gif');
	}
}

scwin.changeZoom = function(newZoom){
	pgjMap.getMap().setZoomLevel(newZoom);
}

scwin.plusZoom = function(){
	pgjMap.getMap().setZoomLevel(pgjMap.getMap().getZoomLevel() + 1)
}

scwin.minusZoom = function(){
	pgjMap.getMap().setZoomLevel(pgjMap.getMap().getZoomLevel() - 1)
}

scwin.sbm_selectCortOfcCdLst_submitdone = function(e){
	const resultData = e.responseJSON;
	try{
		if( resultData.status == 200){

			const sbxItmArr = resultData.data.result;
			for(let i = 0; i < sbxItmArr.length; i++){
				const value = sbxItmArr[i].cortOfcCd;
				const label = sbxItmArr[i].cortOfcNm;
				sbx_excpPrcsCortOfcCd.addItem(value, label, i);
			}
			sbx_excpPrcsCortOfcCd.addItem('', '전체', 0);
		}else{
			scutilo.showMsg("알림창",resultData.message);
		}
	}catch(e){
		scutilo.showMsg("알림창",scutilo.getMsg(pgjmsg.PGJ.E_0002));
	}
}

scwin.vwPpuNote = function(){
	var winW = window.innerWidth;
	var winH = window.innerHeight;

	/* small popup size */
	var popupW = 620;
	var popupH = 590;

	var popupX = (winW/2) - (popupW/2);
	var popupY = (winH/2) - (popupH/2);

	var options = {
		id: "PGJ152P03",
		type: "wframePopup",
		popupName: "유의사항",
		modal: true,
		top:popupY,
		left:popupX,
		width:popupW,
		height:popupH
	};

	com.win.openPopup("/pgj/ui/pgj100/PGJ152P03.xml", options);
}

scwin.trg_ctrl1_onclick = function(){
	pgjMap.setMeasure({mod: '01'});
	scwin.mypinFlag = false
}

scwin.trg_ctrl2_onclick = function(){
	pgjMap.setMeasure({mod: '02'});
	scwin.mypinFlag = false
}

scwin.trg_ctrl3_onclick = function(){
	pgjMap.setMeasure({mod: '03'});
	scwin.mypinFlag = false
}

scwin.trg_ctrl6_onclick = function(){
	window.print()
}
/**
 *
 * 상단에 마이핀(관심지역) 버튼 클릭시 커서 변환 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.07.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
*/
scwin.trg_ctrl4_onclick = function(e) {
	pgjMap.setMeasure({mod: '04'});
	scwin.mypinFlag = true
};

/**
 *
 * 상단에 마이핀(관심지역) 버튼 클릭시 커서 변환 메서드
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.06.13.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
*/
scwin.moveTab = function(tabID,idx,userTabID){

	scwin.mypinFlag = false; // tap 이동시  마이핀초기화
	let wfmCond = "";
	btn_myPin.hide();
	if (idx === 3) {
		btn_myPin.show("");
	} else if(idx === 4){
		if(scwin.tapInit && (scwin.clicked != idx)){ //동일 탭 클릭시 이벤트 X
			wfmCond = wfm_gdsInfo.getWindow();
			wfm_gdsInfo.setSrc("/pgj/ui/pgj100/PGJ152F05.xml");
		}
		scwin.clicked = 4;
	} else if(idx === 5){
		if(scwin.tapInit && (scwin.clicked != idx)){ //동일 탭 클릭시 이벤트 X
			wfmCond = wfm_nearGds.getWindow();
			wfm_gdsInfo.setSrc("/pgj/ui/pgj100/PGJ152F06.xml");
		}
		scwin.tapInit = true;
		scwin.clicked = 5;
	}
}


/**
 *
 * 관심물건,관심지역탭 로그인 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.09.24.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
*/
scwin.tab_mapTapCtr_onbeforeselect = function(selectedIndex,index) {
	if(index === 2 || index === 3){
	 pgjUtil.loginCheckMoveLoginPage().then(result =>{
		if(result){
			//관심물건,관심지역
		} else {
			tab_mapTapCtr.setSelectedTabIndex(0);
			return;
		}
	});
	}
};

/**
 *
 * 집행기관에서 지도버튼 클릭시 발생하는 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.28.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
*/
scwin.tapMoveEvent = function(param) {

	if (!scutilo.isEmpty(param)) {
		const pgmId = param.pgmId;
		const info = param.info;
		switch (true) {
			case ['PGJ182M01','PGJ182F01'].includes(pgmId) :
				tab_mapTapCtr.setSelectedTabIndex(1)
				const arGds = wfm_aroundGds.getWindow()
				arGds.sbx_searchType.setValue('03')
				arGds.sbx_adongSdCd.setUserData('sdCd', info.sdCd || '')
				arGds.sbx_adongSggCd.setUserData('sggCd',info.sggCd || '')
				arGds.sbx_adongEmdCd.setUserData('emdCd',info.emdCd || '')
				arGds.sbx_radius.setUserData('clickYn','Y'),
				arGds.tbx_shopNm.setValue(info.cortSptNm)
			break;
			case ['PGJ15BM01','PGJ151M01','PGJ154M01','PGJ154M03','PGJ155M01','PGJ156M01','PGJ157M01','PGJ193M01'].includes(pgmId) :
				tab_mapTapCtr.hideTab(0);
				tab_mapTapCtr.hideTab(1);
				tab_mapTapCtr.hideTab(2);
				tab_mapTapCtr.hideTab(3);
				tab_mapTapCtr.hideTab(6);
				tab_mapTapCtr.showTab(4);
				tab_mapTapCtr.showTab(5);
			break;
			case ['PGJ151M02', 'PGJ15BM04'].includes(pgmId) :
				tab_mapTapCtr.hideTab(0);
				tab_mapTapCtr.hideTab(1);
				tab_mapTapCtr.hideTab(2);
				tab_mapTapCtr.hideTab(3);
				tab_mapTapCtr.hideTab(4);
				tab_mapTapCtr.hideTab(5);
				tab_mapTapCtr.showTab(6);
			break;
			default: return
		}
	}
}

/**
 *
 * 집행기관에서 지도버튼 클릭시 발생하는 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.15.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.map_onclick = function(e) {
	if(scwin.mypinFlag) {
		let pos = pgjMap.getMap().getCurrentObjectPoint(e);
		pgjMap.removeMarkerByGrp(301) // 관심지역 마커
		scwin.mypinXcordi = pos.x
		scwin.mypinYcordi = pos.y
		let imgSrc = '/pgj/cm/images/map/mypinMarker2.gif'
		let m_Width = 90
		let m_Height = 57
		let markerObj = new FreeMapMarker(new FreeMapPoint(scwin.mypinXcordi, scwin.mypinYcordi), new FreeMapIcon(imgSrc, new FreeMapSize(m_Width, m_Height)));
		pgjMap.getMap().addLayer(markerObj, 301);
		let label = new FreeMapInfoWin();
		markerObj.setLabel(label);
		markerObj.setContents("");
		FreeMapEvent.addListener(markerObj, 'click', scwin.myPinAddEvent);
		markerObj.showLabel(scwin.mypinXcordi, scwin.mypinYcordi);
	} else {
		pgjMap.removeMarkerByGrp(301)
	}
};

/**
 *
 * 관심지역 선택시 추가 한다.
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.myPinAddEvent = function(){
	const zoomLev = pgjMap.getMap().getZoomLevel();
	const itrtArea = wfm_itrtArea.getWindow()

	if(zoomLev < 9){ // 줌레벨 체크
		scutilo.showConfirm(scglblo.MSG.CONFIRM
		, scutilo.getMsg(pgjmsg.PGJ.C_0013)
		, ({clickValue})=>{
            if (clickValue) {
                scwin.changeZoom(9)
				pgjMap.getMap().setCenterAndZoomLevel(scwin.mypinXcordi, scwin.mypinYcordi, 9);
				return;
            } else {
                return
            }
        })
	} else if (!itrtArea.scwin.myPinValidationChk('02')) { //등록갯수 체크
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0063));
		return
	} else if (!itrtArea.scwin.myPinValidationChk('01',scwin.mypinXcordi,scwin.mypinYcordi)) { //반경 체크
		scutilo.showMsg(scglblo.MSG.WARN,scutilo.getMsg(pgjmsg.PGJ.W_0062));
		return
	} else {
		scutilo.showConfirm(scglblo.MSG.INFO,"선택하신 위치를 관심지역으로 등록하시겠습니까?",({clickValue})=>{
			if (clickValue) {
				pgjMap.removeMarkerByGrp(301);
				pgjMap.getGraphics.setDrawMode = 'normal';
				scwin.mypinFlag = 'false'
				dma_createMyPin.set('myPin', '1');
				dma_createMyPin.set('selcNum', '4');
				dma_createMyPin.set('xCordi', scwin.mypinXcordi);
				dma_createMyPin.set('yCordi', scwin.mypinYcordi);
				dma_createMyPin.set('mode', 'create');
				dma_createMyPin.set('cortAuctnMbrsId', scwin.userId);
				com.executeSubmission(sbm_insertMyPinItrtArea);
			} else {
				return;
			}
		})
	}
}

/**
 *
 * 선택한 관심지역 등록후 마커 생성 및 콤보박스 셋팅
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.sbm_insertMyPinItrtArea_submitdone = function({responseJSON:{data,status}}) {
	const result = data.result;
	if (status === 200) {

		const itrtArea = wfm_itrtArea.getWindow()
		const myPinLst = result.myPinLst
		const aroundSrchLst = result.srchLst
		const srchLst = aroundSrchLst.pageResult
		const xCordi = result.xCordi
		const yCordi = result.yCordi

		const filterTitle = result.myPinLst.filter( r => r.bmrkSrchSeq === Number(result.maxBmrkSrchSeq))[0]
		const mapTitle = filterTitle.bmrkDtlLst.filter(r=> r.srchCondNm === "myPinMapAddr" )[0].srchCondVal
		let mkArr = new Array();
		// 관심지역 마커 만들기
		pgjMap(new FreeMapMap('mf_map'));
		pgjMap.getMap().enableWheelZoom();
		pgjMap.makeMarker({
			x: xCordi
			, y: yCordi
			, title: mapTitle
		})
		// 인근지역 마커 만들기 시작
		srchLst.forEach((r,i)=>{
			const markerId = 'marker' + String(i);
			// scwin.markerArr.push(markerId);
			const title = '<span class="marker markerIndex" id="' + markerId + '">'
								+ String(i+1) + '</span>'
								+ String(r.srnSaNo).substr(2).replace('타경', '-')
								+ '[' + String(r.maemulSer) + ']';

			const mkId = 'mk-' + String(i);
			mkArr.push(mkId);
			pgjMap.makeMarker({
				x: r.xCordi
				, y: r.yCordi
				, title
				, mkId
				, imgSrc: '/pgj/cm/images/map/map_area_02.gif'
				, mkGrp: '100'
			})
		})

		const param = {myPinLst,srchLst,mkArr}
		// 관심지역 콤보박스 셋팅
		itrtArea.scwin.insertitrtAreaCallBack(param);
		// 관심지역 해당 좌표로 이동
		pgjMap.getMap().setCenterAndZoomLevel( xCordi, yCordi, 9);
		// 줌 레벨 9로 변환
		scwin.mgnZoomBox(9);
		FreeMapEvent.addListener(pgjMap.getMap(), "zoom", function(newZoom, oldZoom){
			scwin.mgnZoomBox(newZoom);
		})


	}
};

/**
 *
 * 관심지역 콤보박스 선택시 관심지역 목록, 인근지역 조회 콜백함수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.myPinSbxCallBack = function(param) {

	const myPinInfo = param.thisMyPin
	console.log('myPinInfo [1]===>',myPinInfo)
	const rdus = param.rdus || ''
	const mypinXcordi = myPinInfo.bmrkDtlLst.filter(r=> r.srchCondNm === 'myPinXCordi')[0].srchCondVal
	const mypinYcordi = myPinInfo.bmrkDtlLst.filter(r=> r.srchCondNm === 'myPinYCordi')[0].srchCondVal

	// 이전에 그려진 마커들 제거
	pgjMap.removeMarkerByGrp(301); // 관심지역
	pgjMap.removeMarkerByGrp(100); // 인근물건
	scwin.mypinFlag = 'false'

	dma_srchAroundGds.set('myPin', '1');
	dma_srchAroundGds.set('selcNum', '4');
	dma_srchAroundGds.set('bmrkSrchSeq',  myPinInfo.bmrkSrchSeq);
	dma_srchAroundGds.set('mvprpRletDvsCd',  myPinInfo.mvprpRletDvsCd);
	dma_srchAroundGds.set('mvprpRletDvsCd',  myPinInfo.mvprpRletDvsCd);
	dma_srchAroundGds.set('xCordi', mypinXcordi);
	dma_srchAroundGds.set('yCordi', mypinYcordi);
	dma_srchAroundGds.set('srchRdus', rdus);
	dma_srchAroundGds.set('cortAuctnSrchCondCd', '0004605');
	dma_srchAroundGds.set('cortAuctnMbrsId', scwin.userId);
	com.executeSubmission(sbm_selectComboBox);
}

